// Exponential or exponential-adjacent bucket boundaries tailored for web services
// Avoid default buckets (0.005s to 10s) that fail to capture tail latencies accurately
var RequestDuration = prometheus.NewHistogramVec(
    prometheus.HistogramOpts{
        Name:    "http_request_duration_seconds",
        Help:    "HTTP request latency in seconds.",
        Buckets: []float64{0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1.0, 2.5, 5.0},
    },
    // Low cardinality labels ONLY. Never include user_id, email, or unparameterized URLs.
    []string{"method", "route", "status_code"},
)
